test:
assert fit_pair_tokenizer(['ab', 'cd'], 1)['merges'] == [('a', 'b')]
assert fit_pair_tokenizer(['aaa'], 1) == {'merges': [('a', 'a')], 'vocabulary': ['a', 'aa']}
assert encode_pair_tokens('aaa', [('a', 'a')]) == ['aa', 'a']
assert fit_pair_tokenizer([], 5) == {'merges': [], 'vocabulary': []}

assert fit_pair_tokenizer(['ab', 'bc', 'bc'], 1) == {'merges': [('b', 'c')], 'vocabulary': ['a', 'b', 'bc']}
assert fit_pair_tokenizer(['a', 'b'], 3) == {'merges': [], 'vocabulary': ['a', 'b']}
assert fit_pair_tokenizer(['猫猫猫'], 1) == {'merges': [('猫', '猫')], 'vocabulary': ['猫', '猫猫']}
assert encode_pair_tokens('猫猫猫', [('猫', '猫')]) == ['猫猫', '猫']
assert fit_pair_tokenizer(['ba'], 0) == {'merges': [], 'vocabulary': ['a', 'b']}
assert encode_pair_tokens('', [('a', 'b')]) == []
